const HTML = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Mira - Estudos</title>\n    <link rel=\"stylesheet\" href=\"https://fonts.cdnfonts.com/css/rawline\">\n    <style>* {\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n}\n\n:root {\n    --primary-color: #095B83;\n    --primary-dark: #074a6a;\n    --primary-darker: #063d58;\n    --bg-light: #f5f5f5;\n    --bg-white: #ffffff;\n    --text-dark: #333333;\n    --text-gray: #666666;\n    --border-color: #e0e0e0;\n    --pdf-bg: #c8c3bb;\n}\n\nbody {\n    font-family: 'Rawline', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n    background-color: var(--bg-light);\n    color: var(--text-dark);\n    min-height: 100vh;\n}\n\n/* Header */\n.header {\n    background: linear-gradient(135deg, #063d58 0%, #095B83 100%);\n    color: white;\n    padding: 0 24px;\n    height: 56px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n}\n\n.header-left {\n    display: flex;\n    align-items: center;\n    gap: 40px;\n}\n\n.logo {\n    display: flex;\n    flex-direction: column;\n    line-height: 1;\n}\n\n.logo-text {\n    font-size: 24px;\n    font-weight: 700;\n    letter-spacing: -0.5px;\n}\n\n.logo-subtitle {\n    font-size: 9px;\n    letter-spacing: 2px;\n    opacity: 0.8;\n    margin-top: 2px;\n}\n\n.nav {\n    display: flex;\n    gap: 4px;\n}\n\n.nav-item {\n    color: white;\n    text-decoration: none;\n    padding: 8px 14px;\n    font-size: 14px;\n    font-weight: 500;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    transition: background-color 0.2s;\n}\n\n.nav-item:hover {\n    background-color: rgba(255,255,255,0.1);\n}\n\n.nav-item.active {\n    background-color: rgba(255,255,255,0.15);\n}\n\n.nav-icon {\n    width: 18px;\n    height: 18px;\n    opacity: 0.9;\n}\n\n.header-right {\n    display: flex;\n    align-items: center;\n}\n\n.user-profile {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    cursor: pointer;\n}\n\n.user-avatar {\n    width: 36px;\n    height: 36px;\n    background-color: rgba(255,255,255,0.2);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-weight: 600;\n    font-size: 13px;\n}\n\n.user-name {\n    font-weight: 500;\n    font-size: 14px;\n}\n\n.menu-icon {\n    width: 20px;\n    height: 20px;\n    opacity: 0.8;\n}\n\n/* Main Content */\n.main-content {\n    display: flex;\n    height: calc(100vh - 56px);\n}\n\n/* PDF Panel */\n.pdf-panel {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    background-color: var(--pdf-bg);\n}\n\n.pdf-header {\n    padding: 10px 16px;\n    background-color: transparent;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n\n.pdf-icon {\n    width: 18px;\n    height: 18px;\n    color: var(--text-gray);\n    opacity: 0.7;\n}\n\n.pdf-title {\n    font-size: 13px;\n    color: var(--text-gray);\n}\n\n.pdf-viewer {\n    flex: 1;\n    overflow: auto;\n    padding: 0 20px 20px 20px;\n    position: relative;\n}\n\n.pdf-content {\n    background-color: white;\n    box-shadow: 0 2px 20px rgba(0,0,0,0.15);\n    padding: 40px 50px;\n    max-width: 100%;\n    min-height: calc(100vh - 120px);\n}\n\n.pdf-page {\n    line-height: 1.7;\n    font-size: 14px;\n    color: #1a1a1a;\n}\n\n.pdf-page p {\n    margin-bottom: 10px;\n}\n\n/* Question Panel */\n.question-panel {\n    width: 440px;\n    background-color: var(--bg-white);\n    display: flex;\n    flex-direction: column;\n    overflow-y: auto;\n    border-left: 1px solid var(--border-color);\n}\n\n.question-header {\n    padding: 20px 24px;\n    border-bottom: 2px solid #095B83;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n.question-number {\n    font-size: 20px;\n    font-weight: 600;\n    color: var(--text-dark);\n}\n\n/* Clock */\n.clock-container {\n    background-color: #f8fafc;\n    border: 1px solid var(--border-color);\n    padding: 0;\n}\n\n.clock-inner {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    padding: 6px 12px;\n}\n\n.clock-icon {\n    width: 16px;\n    height: 16px;\n    color: var(--text-gray);\n    opacity: 0.7;\n}\n\n.clock-label {\n    font-size: 10px;\n    font-weight: 600;\n    color: var(--text-gray);\n    letter-spacing: 0.5px;\n}\n\n.clock-time {\n    font-size: 16px;\n    font-weight: 700;\n    color: #095B83;\n    font-family: 'Rawline', 'Courier New', monospace;\n    font-variant-numeric: tabular-nums;\n}\n\n/* Question Index */\n.question-index {\n    border-bottom: none;\n    height: 100px;\n    display: flex;\n    flex-direction: column;\n}\n\n.index-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 10px 12px 6px;\n    flex-shrink: 0;\n    background-color: var(--bg-white);\n}\n\n.index-title {\n    font-size: 10px;\n    font-weight: 600;\n    color: var(--text-gray);\n    letter-spacing: 0.5px;\n}\n\n.index-count {\n    font-size: 11px;\n    color: var(--text-gray);\n}\n\n.index-grid {\n    display: grid;\n    grid-template-columns: repeat(15, 1fr);\n    gap: 3px;\n    overflow-y: auto;\n    flex: 1;\n    padding: 0 12px 8px;\n    scroll-behavior: smooth;\n}\n\n.index-grid::-webkit-scrollbar {\n    width: 3px;\n}\n\n.index-grid::-webkit-scrollbar-track {\n    background: #f5f5f5;\n}\n\n.index-grid::-webkit-scrollbar-thumb {\n    background: #ccc;\n    border-radius: 2px;\n}\n\n.index-btn {\n    width: 100%;\n    aspect-ratio: 1;\n    border: 1px solid #eee;\n    background-color: #fcfcfc;\n    font-size: 10px;\n    font-weight: 500;\n    color: #999;\n    cursor: pointer;\n    transition: all 0.2s ease;\n    padding: 0;\n    min-height: 20px;\n    min-width: 20px;\n}\n\n.index-btn:hover {\n    border-color: #ddd;\n    background-color: #f6f6f6;\n    color: #666;\n}\n\n.index-btn.null {\n    background-color: #f7f7f7;\n    border-color: #e6e6e6;\n    color: #aaa;\n}\n\n.index-btn.wrong-answer {\n    background-color: #fdf2f2;\n    border-color: #f5d5d5;\n    color: #c97070;\n}\n\n.index-btn.correct-answer {\n    background-color: #f2fdf2;\n    border-color: #d5f0d5;\n    color: #70a870;\n}\n\n.index-btn.active {\n    background-color: #095B83;\n    border-color: #095B83;\n    color: white;\n    font-weight: 700;\n}\n\n.index-contrast .index-btn.null {\n    background-color: #f0f0f0;\n    border-color: #ddd;\n    color: #888;\n}\n\n.index-contrast .index-btn.correct-answer {\n    background-color: #d4edda;\n    border-color: #a3d9b1;\n    color: #155724;\n}\n\n.index-contrast .index-btn.wrong-answer {\n    background-color: #f8d7da;\n    border-color: #f1aeb5;\n    color: #721c24;\n}\n\n/* Answer Section */\n.answer-section {\n    padding: 16px 20px;\n}\n\n.answer-section.changing {\n    animation: fadeOut 0.15s ease forwards;\n}\n\n@keyframes fadeIn {\n    from { opacity: 0; transform: translateY(10px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n\n@keyframes fadeOut {\n    from { opacity: 1; transform: translateY(0); }\n    to { opacity: 0; transform: translateY(-10px); }\n}\n\n.answer-title {\n    font-size: 11px;\n    font-weight: 600;\n    color: var(--text-gray);\n    letter-spacing: 0.5px;\n    margin-bottom: 14px;\n}\n\n.option {\n    display: flex;\n    align-items: flex-start;\n    gap: 14px;\n    padding: 14px 16px;\n    border: 1px solid #e2e8f0;\n    margin-bottom: 10px;\n    cursor: pointer;\n    transition: all 0.25s ease;\n    background-color: var(--bg-white);\n}\n\n.option:hover {\n    border-color: #095B83;\n    background-color: #f0f7fa;\n    transform: translateX(2px);\n}\n\n.option.selected {\n    border-color: #095B83;\n    background-color: #e3f0f7;\n    transform: translateX(2px);\n    box-shadow: 0 1px 3px rgba(9, 91, 131, 0.1);\n}\n\n.option.disabled {\n    pointer-events: none;\n}\n\n.option.correct-highlight {\n    border-color: #4caf50;\n    background-color: #e8f5e9;\n}\n\n.option.correct-highlight .option-letter {\n    background-color: #4caf50;\n    color: white;\n}\n\n.option.wrong-highlight {\n    border-color: #fc8181;\n    background-color: #fff5f5;\n    opacity: 0.6;\n}\n\n.option-letter {\n    width: 34px;\n    height: 34px;\n    background-color: #f1f5f9;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-weight: 600;\n    font-size: 13px;\n    color: var(--text-gray);\n    flex-shrink: 0;\n    transition: all 0.25s ease;\n}\n\n.option.selected .option-letter {\n    background-color: #095B83;\n    color: white;\n    transform: scale(1.05);\n}\n\n.option-text {\n    font-size: 13px;\n    color: var(--text-dark);\n    line-height: 1.5;\n    padding-top: 6px;\n}\n\n/* Feedback */\n.feedback {\n    margin: 0 20px 20px;\n    padding: 14px 16px;\n    border-left: 4px solid;\n    animation: feedbackSlideIn 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);\n}\n\n.feedback.correct {\n    background-color: #e8f5e9;\n    border-color: #4caf50;\n}\n\n.feedback.incorrect {\n    background-color: #fff5f5;\n    border-color: #fc8181;\n}\n\n@keyframes feedbackSlideIn {\n    0% { opacity: 0; transform: translateY(15px) scale(0.98); }\n    60% { transform: translateY(-2px) scale(1.01); }\n    100% { opacity: 1; transform: translateY(0) scale(1); }\n}\n\n.feedback-label {\n    font-size: 11px;\n    color: var(--text-gray);\n    margin-bottom: 2px;\n}\n\n.feedback-text {\n    font-size: 15px;\n    font-weight: 600;\n}\n\n.feedback.correct .feedback-text {\n    color: #2e7d32;\n}\n\n.feedback.incorrect .feedback-text {\n    color: #c53030;\n}\n\n/* Bottom Navigation */\n.bottom-nav {\n    margin-top: auto;\n    padding: 20px 24px;\n    border-top: 1px solid #eee;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    background-color: var(--bg-white);\n    transition: all 0.3s ease;\n}\n\n.nav-arrows {\n    display: flex;\n    gap: 8px;\n    transition: all 0.3s ease;\n}\n\n.nav-arrow {\n    width: 44px;\n    height: 44px;\n    border: 1px solid #e0e0e0;\n    background-color: #fafafa;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n    transition: all 0.2s ease;\n    color: #888;\n}\n\n.nav-arrow:hover {\n    border-color: #095B83;\n    color: #095B83;\n    background-color: #f0f7fa;\n}\n\n.bottom-nav.feedback-active .nav-arrows {\n    transform: scale(0.7);\n    opacity: 0.5;\n    pointer-events: none;\n}\n\n.bottom-nav.feedback-active .btn-respond {\n    background-color: #095B83;\n    flex: 1;\n    max-width: 300px;\n}\n\n.btn-respond {\n    padding: 14px 40px;\n    background-color: #999;\n    color: white;\n    border: none;\n    font-size: 14px;\n    font-weight: 600;\n    cursor: pointer;\n    transition: all 0.2s ease;\n    letter-spacing: 0.3px;\n}\n\n.btn-respond:hover {\n    background-color: #777;\n}\n\n/* Responsive */\n@media (max-width: 1024px) {\n    .main-content {\n        flex-direction: column;\n    }\n    .pdf-panel {\n        height: 50vh;\n        border-right: none;\n        border-bottom: 1px solid var(--border-color);\n    }\n    .question-panel {\n        width: 100%;\n    }\n}\n\n@media (max-width: 640px) {\n    .header {\n        padding: 0 16px;\n    }\n    .nav {\n        display: none;\n    }\n    .index-grid {\n        grid-template-columns: repeat(10, 1fr);\n    }\n}</style>\n</head>\n<body>\n    <header class=\"header\">\n        <div class=\"header-left\">\n            <div class=\"logo\">\n                <span class=\"logo-text\">Mira</span>\n                <span class=\"logo-subtitle\">ESTUDOS</span>\n            </div>\n            <nav class=\"nav\">\n                <a href=\"#\" class=\"nav-item active\">\n                    <svg class=\"nav-icon\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"></line><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"></line><polyline points=\"10 9 9 9 8 9\"></polyline></svg>\n                    Provas\n                </a>\n                <a href=\"#\" class=\"nav-item\">\n                    <svg class=\"nav-icon\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"20\" x2=\"18\" y2=\"10\"></line><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"4\"></line><line x1=\"6\" y1=\"20\" x2=\"6\" y2=\"14\"></line></svg>\n                    Desempenho\n                </a>\n            </nav>\n        </div>\n        <div class=\"header-right\">\n            <div class=\"user-profile\">\n                <div class=\"user-avatar\">LA</div>\n                <span class=\"user-name\">Lucas</span>\n                <svg class=\"menu-icon\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"3\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"3\" y1=\"18\" x2=\"21\" y2=\"18\"></line></svg>\n            </div>\n        </div>\n    </header>\n\n    <main class=\"main-content\">\n        <section class=\"pdf-panel\">\n            <div class=\"pdf-header\">\n                <svg class=\"pdf-icon\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline></svg>\n                <span class=\"pdf-title\">Questão 1 no PDF</span>\n            </div>\n            <div class=\"pdf-viewer\">\n                <div class=\"pdf-content\">\n                    <div class=\"pdf-page\" id=\"pdf-content\">\n                        <p>Carregando questão...</p>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <section class=\"question-panel\">\n            <div class=\"question-header\">\n                <h2 class=\"question-number\">Questão 1</h2>\n                <div class=\"clock-container\">\n                    <div class=\"clock-inner\">\n                        <svg class=\"clock-icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><polyline points=\"12 6 12 12 16 14\"></polyline></svg>\n                        <span class=\"clock-label\">TEMPO DE PROVA</span>\n                        <span class=\"clock-time\" id=\"clock-time\">02:00:00</span>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"question-index\">\n                <div class=\"index-header\">\n                    <span class=\"index-title\">ÍNDICE DE QUESTÕES</span>\n                    <span class=\"index-count\">1/10</span>\n                </div>\n                <div class=\"index-grid\" id=\"index-grid\"></div>\n            </div>\n\n            <div class=\"answer-section\" id=\"answer-section\">\n                <h3 class=\"answer-title\">ESCOLHA UMA RESPOSTA</h3>\n                <div class=\"option\" data-option=\"A\"><div class=\"option-letter\">A</div><div class=\"option-text\"></div></div>\n                <div class=\"option\" data-option=\"B\"><div class=\"option-letter\">B</div><div class=\"option-text\"></div></div>\n                <div class=\"option\" data-option=\"C\"><div class=\"option-letter\">C</div><div class=\"option-text\"></div></div>\n                <div class=\"option\" data-option=\"D\"><div class=\"option-letter\">D</div><div class=\"option-text\"></div></div>\n                <div class=\"option\" data-option=\"E\"><div class=\"option-letter\">E</div><div class=\"option-text\"></div></div>\n            </div>\n\n            <div class=\"feedback\" id=\"feedback\" style=\"display:none;\"></div>\n\n            <div class=\"bottom-nav\" id=\"bottom-nav\">\n                <div class=\"nav-arrows\">\n                    <button class=\"nav-arrow\" id=\"prev-btn\">\n                        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"15 18 9 12 15 6\"></polyline></svg>\n                    </button>\n                    <button class=\"nav-arrow\" id=\"next-btn\">\n                        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>\n                    </button>\n                </div>\n                <button class=\"btn-respond\" id=\"respond-btn\">Responder</button>\n            </div>\n        </section>\n    </main>\n\n    <script>document.addEventListener('DOMContentLoaded', function() {\n    const totalQuestions = 10;\n    let currentQuestion = 1;\n    let selectedAnswer = null;\n    let respondMode = 'answer';\n\n    // Questões reais de Português\n    const questions = {\n        1: {\n            text: 'Assinale a alternativa em que todas as palavras estão classificadas corretamente quanto aos tempos verbais indicados.',\n            options: [\n                { letter: 'A', text: 'presente do indicativo, imperativo, presente do indicativo, presente do indicativo, presente do indicativo, presente do indicativo, pretérito perfeito do indicativo, imperativo, presente do subjuntivo, infinitivo, imperfeito do indicativo.' },\n                { letter: 'B', text: 'presente do indicativo, imperativo, presente do indicativo, presente do indicativo, presente do indicativo, presente do indicativo, pretérito imperfeito do indicativo, imperativo, presente do subjuntivo, infinitivo, imperfeito do indicativo.' },\n                { letter: 'C', text: 'presente do subjuntivo, imperativo, presente do indicativo, presente do indicativo, presente do indicativo, presente do indicativo, pretérito perfeito do indicativo, imperativo, presente do subjuntivo, infinitivo, imperfeito do indicativo.' },\n                { letter: 'D', text: 'presente do indicativo, imperativo, presente do indicativo, presente do indicativo, presente do indicativo, presente do indicativo, pretérito perfeito do indicativo, imperativo, presente do subjuntivo, infinitivo, futuro do pretérito.' },\n                { letter: 'E', text: 'presente do subjuntivo, imperativo, presente do indicativo, presente do indicativo, presente do indicativo, presente do indicativo, pretérito perfeito do indicativo, imperativo, presente do subjuntivo, infinitivo, imperfeito do indicativo.' }\n            ],\n            correct: 'A'\n        },\n        2: {\n            text: 'Assinale a alternativa em que a classificação dos tempos verbais está CORRETA.',\n            options: [\n                { letter: 'A', text: 'pretérito perfeito do indicativo, futuro do presente, presente do subjuntivo, imperativo afirmativo, condicional.' },\n                { letter: 'B', text: 'pretérito imperfeito do indicativo, futuro do presente, presente do subjuntivo, imperativo afirmativo, condicional.' },\n                { letter: 'C', text: 'pretérito perfeito do indicativo, futuro do pretérito, presente do subjuntivo, imperativo afirmativo, condicional.' },\n                { letter: 'D', text: 'pretérito perfeito do indicativo, futuro do presente, pretérito imperfeito do subjuntivo, imperativo afirmativo, condicional.' },\n                { letter: 'E', text: 'pretérito perfeito do indicativo, futuro do presente, presente do subjuntivo, imperativo negativo, condicional.' }\n            ],\n            correct: 'A'\n        },\n        3: {\n            text: 'Em \"Se eu pudesse, viajaria pelo mundo inteiro\", os tempos verbais são, respectivamente:',\n            options: [\n                { letter: 'A', text: 'presente do subjuntivo e futuro do pretérito do indicativo.' },\n                { letter: 'B', text: 'pretérito imperfeito do subjuntivo e condicional.' },\n                { letter: 'C', text: 'presente do subjuntivo e condicional.' },\n                { letter: 'D', text: 'pretérito imperfeito do subjuntivo e futuro do presente do indicativo.' },\n                { letter: 'E', text: 'presente do indicativo e futuro do pretérito do indicativo.' }\n            ],\n            correct: 'B'\n        },\n        4: {\n            text: 'Assinale a frase em que o verbo está no pretérito perfeito composto do indicativo.',\n            options: [\n                { letter: 'A', text: 'Eu estivera estudando para a prova.' },\n                { letter: 'B', text: 'Eu estava estudando para a prova.' },\n                { letter: 'C', text: 'Eu estudo para a prova.' },\n                { letter: 'D', text: 'Eu havia estudado para a prova.' },\n                { letter: 'E', text: 'Eu estarei estudando para a prova.' }\n            ],\n            correct: 'B'\n        },\n        5: {\n            text: 'Em \"Quando eu chegar, você já terá saído\", os tempos verbais são:',\n            options: [\n                { letter: 'A', text: 'futuro do presente do indicativo e futuro perfeito do indicativo.' },\n                { letter: 'B', text: 'presente do subjuntivo e futuro perfeito do indicativo.' },\n                { letter: 'C', text: 'futuro do presente do indicativo e pretérito perfeito composto do indicativo.' },\n                { letter: 'D', text: 'presente do subjuntivo e pretérito perfeito composto do indicativo.' },\n                { letter: 'E', text: 'futuro do pretérito e futuro perfeito do indicativo.' }\n            ],\n            correct: 'A'\n        },\n        6: {\n            text: 'Assinale a alternativa em que o verbo está no imperativo negativo.',\n            options: [\n                { letter: 'A', text: 'Não faça isso!' },\n                { letter: 'B', text: 'Você não faz isso.' },\n                { letter: 'C', text: 'Você não faria isso.' },\n                { letter: 'D', text: 'Não faria isso!' },\n                { letter: 'E', text: 'Você não fará isso.' }\n            ],\n            correct: 'A'\n        },\n        7: {\n            text: 'Embora estivesse cansado, ele continuou trabalhando. O verbo \"estivesse\" está no:',\n            options: [\n                { letter: 'A', text: 'presente do subjuntivo.' },\n                { letter: 'B', text: 'pretérito imperfeito do subjuntivo.' },\n                { letter: 'C', text: 'futuro do subjuntivo.' },\n                { letter: 'D', text: 'pretérito perfeito do subjuntivo.' },\n                { letter: 'E', text: 'condicional.' }\n            ],\n            correct: 'B'\n        },\n        8: {\n            text: 'Assinale a frase em que o verbo está no futuro do presente do indicativo.',\n            options: [\n                { letter: 'A', text: 'Quando chegar a hora, partirei.' },\n                { letter: 'B', text: 'Quando cheguei a hora, parti.' },\n                { letter: 'C', text: 'Quando chegar a hora, partiria.' },\n                { letter: 'D', text: 'Quando chegar a hora, partisse.' },\n                { letter: 'E', text: 'Quando chegar a hora, terei partido.' }\n            ],\n            correct: 'A'\n        },\n        9: {\n            text: 'Se eu tivesse dinheiro, compraria uma casa. Os tempos verbais são:',\n            options: [\n                { letter: 'A', text: 'presente do subjuntivo e futuro do pretérito do indicativo.' },\n                { letter: 'B', text: 'pretérito perfeito do subjuntivo e condicional.' },\n                { letter: 'C', text: 'pretérito imperfeito do subjuntivo e condicional.' },\n                { letter: 'D', text: 'presente do indicativo e futuro do presente do indicativo.' },\n                { letter: 'E', text: 'pretérito imperfeito do subjuntivo e futuro do pretérito do indicativo.' }\n            ],\n            correct: 'C'\n        },\n        10: {\n            text: 'Assinale a alternativa em que todos os verbos estão no pretérito imperfeito do indicativo.',\n            options: [\n                { letter: 'A', text: 'Eu caminhava, cantava e dançava.' },\n                { letter: 'B', text: 'Eu caminhei, cantei e dancei.' },\n                { letter: 'C', text: 'Eu caminharia, cantaria e dançaria.' },\n                { letter: 'D', text: 'Eu caminhasse, cantasse e dançasse.' },\n                { letter: 'E', text: 'Eu caminharei, cantarei e dançarei.' }\n            ],\n            correct: 'A'\n        }\n    };\n\n    const correctAnswers = {};\n    for (let i = 1; i <= totalQuestions; i++) {\n        correctAnswers[i] = questions[i].correct;\n    }\n\n    const indexGrid = document.getElementById('index-grid');\n    const questionResults = {};\n    const COLS = 15;\n    const ROW_HEIGHT = 22;\n\n    function renderIndex() {\n        indexGrid.innerHTML = '';\n        for (let i = 1; i <= totalQuestions; i++) {\n            const btn = document.createElement('button');\n            btn.className = 'index-btn';\n            btn.textContent = i;\n            btn.dataset.question = i;\n\n            if (i === currentQuestion) {\n                btn.classList.add('active');\n            } else if (questionResults[i] === 'correct') {\n                btn.classList.add('correct-answer');\n            } else if (questionResults[i] === 'wrong') {\n                btn.classList.add('wrong-answer');\n            } else {\n                btn.classList.add('null');\n            }\n\n            btn.addEventListener('click', () => goToQuestion(i));\n            indexGrid.appendChild(btn);\n        }\n        scrollToActive();\n    }\n\n    function scrollToActive() {\n        const grid = document.getElementById('index-grid');\n        if (!grid) return;\n        const rowIndex = Math.floor((currentQuestion - 1) / COLS);\n        const scrollTarget = rowIndex * ROW_HEIGHT;\n        const maxScroll = grid.scrollHeight - grid.clientHeight;\n        const start = grid.scrollTop;\n        const change = Math.min(scrollTarget, maxScroll) - start;\n        const duration = 400;\n        let startTime = null;\n\n        function animate(currentTime) {\n            if (!startTime) startTime = currentTime;\n            const elapsed = currentTime - startTime;\n            const progress = Math.min(elapsed / duration, 1);\n            const easeOut = 1 - Math.pow(1 - progress, 3);\n            grid.scrollTop = start + change * easeOut;\n            if (progress < 1) requestAnimationFrame(animate);\n        }\n        requestAnimationFrame(animate);\n    }\n\n    function goToQuestion(num, animate = true) {\n        if (num === currentQuestion) return;\n        const answerSection = document.getElementById('answer-section');\n        const feedback = document.getElementById('feedback');\n        const questionIndex = document.querySelector('.question-index');\n        const bottomNav = document.getElementById('bottom-nav');\n\n        questionIndex.classList.remove('index-contrast');\n        bottomNav.classList.remove('feedback-active');\n\n        if (animate) {\n            answerSection.classList.add('changing');\n            setTimeout(() => {\n                currentQuestion = num;\n                selectedAnswer = null;\n                updateQuestion();\n                renderIndex();\n                answerSection.classList.remove('changing');\n            }, 200);\n        } else {\n            currentQuestion = num;\n            selectedAnswer = null;\n            updateQuestion();\n            renderIndex();\n        }\n    }\n\n    function updateQuestion() {\n        const q = questions[currentQuestion];\n        document.querySelector('.question-number').textContent = `Questão ${currentQuestion}`;\n        document.querySelector('.pdf-title').textContent = `Questão ${currentQuestion} no PDF`;\n        document.querySelector('.index-count').textContent = `${currentQuestion}/${totalQuestions}`;\n\n        // Atualiza conteúdo do PDF\n        const pdfContent = document.getElementById('pdf-content');\n        pdfContent.innerHTML = `<p><strong>${currentQuestion}.</strong> ${q.text}</p>`;\n\n        // Atualiza opções\n        const options = document.querySelectorAll('.option');\n        options.forEach((opt, i) => {\n            opt.classList.remove('selected', 'disabled', 'correct-highlight', 'wrong-highlight');\n            if (q.options[i]) {\n                opt.querySelector('.option-text').textContent = q.options[i].text;\n                opt.style.display = 'flex';\n            } else {\n                opt.style.display = 'none';\n            }\n        });\n\n        const feedback = document.getElementById('feedback');\n        feedback.className = 'feedback';\n        feedback.style.display = 'none';\n\n        respondMode = 'answer';\n        document.getElementById('respond-btn').textContent = 'Responder';\n        document.getElementById('respond-btn').disabled = false;\n    }\n\n    // Seleção de opção\n    const options = document.querySelectorAll('.option');\n    options.forEach(option => {\n        option.addEventListener('click', function() {\n            if (this.classList.contains('disabled')) return;\n            options.forEach(opt => opt.classList.remove('selected'));\n            this.classList.add('selected');\n            selectedAnswer = this.dataset.option;\n        });\n    });\n\n    // Botão Responder/Avançar\n    document.getElementById('respond-btn').addEventListener('click', function() {\n        if (respondMode === 'answer') {\n            if (!selectedAnswer) {\n                alert('Selecione uma opção antes de responder.');\n                return;\n            }\n\n            const feedback = document.getElementById('feedback');\n            const questionIndex = document.querySelector('.question-index');\n            const bottomNav = document.getElementById('bottom-nav');\n            const isCorrect = selectedAnswer === correctAnswers[currentQuestion];\n            const correctLetter = correctAnswers[currentQuestion];\n\n            feedback.style.display = 'block';\n            feedback.className = `feedback ${isCorrect ? 'correct' : 'incorrect'}`;\n            feedback.innerHTML = `\n                <div class=\"feedback-label\">Feedback:</div>\n                <div class=\"feedback-text\">${isCorrect ? 'Resposta correta!' : `Resposta incorreta. A correta é: ${correctLetter}`}</div>\n            `;\n\n            options.forEach(opt => {\n                if (opt.dataset.option === correctLetter) {\n                    opt.classList.add('correct-highlight');\n                } else if (opt.classList.contains('selected')) {\n                    opt.classList.add('wrong-highlight');\n                }\n                opt.classList.add('disabled');\n            });\n\n            questionResults[currentQuestion] = isCorrect ? 'correct' : 'wrong';\n            questionIndex.classList.add('index-contrast');\n            bottomNav.classList.add('feedback-active');\n\n            // Animação no índice\n            const btn = indexGrid.querySelector(`[data-question=\"${currentQuestion}\"]`);\n            if (btn) {\n                btn.classList.add(isCorrect ? 'animate-correct' : 'animate-wrong');\n                setTimeout(() => {\n                    btn.classList.remove('animate-correct', 'animate-wrong', 'active');\n                    btn.classList.add(isCorrect ? 'correct-answer' : 'wrong-answer');\n                }, 500);\n            }\n\n            respondMode = 'next';\n            this.textContent = 'Avançar';\n        } else {\n            if (currentQuestion < totalQuestions) {\n                goToQuestion(currentQuestion + 1);\n            }\n            respondMode = 'answer';\n            this.textContent = 'Responder';\n        }\n    });\n\n    // Navegação\n    document.getElementById('prev-btn').addEventListener('click', function() {\n        if (currentQuestion > 1) goToQuestion(currentQuestion - 1);\n    });\n\n    document.getElementById('next-btn').addEventListener('click', function() {\n        if (currentQuestion < totalQuestions) goToQuestion(currentQuestion + 1);\n    });\n\n    // Relógio\n    let timeInSeconds = 2 * 60 * 60; // 2 horas\n    const clockDisplay = document.getElementById('clock-time');\n\n    function updateClock() {\n        const h = Math.floor(timeInSeconds / 3600);\n        const m = Math.floor((timeInSeconds % 3600) / 60);\n        const s = timeInSeconds % 60;\n        clockDisplay.textContent = `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;\n    }\n\n    setInterval(() => {\n        if (timeInSeconds > 0) {\n            timeInSeconds--;\n            updateClock();\n        }\n    }, 1000);\n\n    // Init\n    renderIndex();\n    updateQuestion();\n    updateClock();\n});</script>\n</body>\n</html>";
export default {
  fetch() {
    return new Response(HTML, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store"
      }
    });
  }
};
